const inaFlag={src:"assets/flags/italy-kingdom.svg",alt:"Flag of the Kingdom of Italy",caption:"The royal Italian tricolor represents sovereignty. No separate sovereign North African flag is registered."};
const inaRelated=[{href:"italy.html",kicker:"Metropolitan sovereign",label:"Kingdom of Italy"},{href:"latin-bloc.html",kicker:"Bloc context",label:"Latin Bloc"},{href:"egypt.html",kicker:"Eastern system",label:"Kingdom of Egypt"},{href:"italian-east-africa.html",kicker:"Red Sea empire",label:"Italian East Africa"}];
function inaArticle(d){return{title:d.title,category:d.category||"Italian North Africa",eyebrow:d.eyebrow,infoboxKicker:d.infoboxKicker,infoboxTitle:d.infoboxTitle||d.title,lead:d.lead,canon:d.canon,sections:d.sections,related:d.related||inaRelated,sources:d.sources||inaSources,categories:d.categories||[d.title,"Italian North Africa","Italian Empire"],facts:d.facts,flag:d.flag,landscape:d.landscape};}

Object.assign(window.deepArticles,{
  "italian-north-africa":inaArticle({title:"Italian North Africa",eyebrow:"Libya · Tunisia · Algeria · Sahara · 1985",infoboxKicker:"Imperial operating sphere",infoboxTitle:"Africa Settentrionale Italiana",flag:inaFlag,
    lead:"Italian North Africa is the collective operating sphere through which Rome governs Libya, Tunisia, Algeria, and the Saharan acquisitions. It is not one ordinary colony. Coastal Libya is treated as Italy's inner colonial extension, Tunisia retains compact inherited machinery under supervision, Algeria remains a French colonial society beneath Italian sovereignty, and the Sahara is governed through routes, oases, airfields, radio posts, and concessions.",
    canon:"The four differentiated systems, Italian strategic control, coastal integration, mixed settler societies, local and inherited institutions, Christian institutional preference, Muslim continuity, corridor security, and incomplete interior reach are established. Collective official title, exact frontiers, governor hierarchy, population, censuses, flags, 1985 officeholders, and a common legislature remain open.",
    sections:[
      {id:"settlement",title:"An empire inherited by victory",html:"<p>Italy enters the postwar settlement with Libya already under long colonial rule and acquires wider authority across Tunisia, Algeria, and Saharan territories after the defeat of France and Britain. Rome inherits people, laws, municipalities, banks, ports, and conflicts that cannot be standardized by decree.</p>"},
      {id:"layers",title:"Four administrative depths",html:"<figure class='archive-map-figure'><a href='assets/italian-north-africa-authority.svg'><img src='assets/italian-north-africa-authority.svg' alt='Diagram comparing four forms of Italian North African rule'></a><figcaption>Italian sovereignty sits above four distinct operating systems rather than one uniform colonial administration.</figcaption></figure><p><a href='italian-libya.html'>Libya</a> receives the deepest direct integration. <a href='italian-tunisia.html'>Tunisia</a> preserves local and French machinery beneath supervision. <a href='italian-algeria.html'>Algeria</a> retains French-speaking institutions that Italy cannot replace. The <a href='italian-sahara.html'>Sahara</a> is a strategic geography of points and lines.</p>"},
      {id:"coast",title:"The Mediterranean coast",html:"<p>Tripoli, Benghazi, Tunis, Bizerte, Algiers, and other ports carry customs, naval access, migration, investment, police, and communications. Short sea routes to Sicily and peninsular Italy make the coast more governable than the interior.</p>"},
      {id:"society",title:"Settlers and local institutions",html:"<p>Italian, French, Maltese, Jewish, Arab, Berber, Greek, Spanish, Occitan, and Levantine communities occupy different positions across the region. Rome preserves useful officials, firms, courts, and municipalities while shifting sovereignty, concessions, credit, and strategic command toward Italy.</p>"},
      {id:"religion",title:"Religious policy",html:"<p>The <a href='north-african-religious-policy.html'>religious settlement</a> favors Christian schools, settlement, conversion, refugee placement, and public careers. Islam remains legal and necessary to government. Jewish communities remain commercially and urbanly important, though their exact legal settlement is open.</p>"},
      {id:"security",title:"Security and divided opposition",html:"<p>The <a href='north-african-colonial-security.html'>security system</a> controls ports, trunk roads, airfields, railways, customs, police headquarters, and mobile reserves. In Algeria especially, Rome works to prevent French restorationists, Arab and Berber nationalists, and alienated settlers from forming a common front.</p>"},
      {id:"economy",title:"Lira, francs, and concessions",html:"<p>Lira circulation grows fastest in Libya and Tunisia. French money, commercial law, banks, and accounts persist longer in Algeria. Italian firms receive preferred concessions and credit, while ports, agriculture, food, phosphates, minerals, transit, and consumer markets tie the region to metropolitan reconstruction.</p>"},
      {id:"1985",title:"North Africa in 1985",html:"<p>By 1985 the coast is a permanent Italian strategic system, not a temporary occupation zone. Administrative depth still declines inland and varies by territory. Integration has made the empire durable while preserving the distinct societies that contest it.</p>"}
    ],related:[{href:"italian-libya.html",kicker:"Inner colony",label:"Italian Libya"},{href:"italian-tunisia.html",kicker:"Supervised territory",label:"Italian Tunisia"},{href:"italian-algeria.html",kicker:"Inherited settler society",label:"Italian Algeria"},{href:"italian-sahara.html",kicker:"Strategic interior",label:"Italian Sahara"},...inaRelated],
    facts:[["Sovereign power","Kingdom of Italy"],["Operating territories","Libya, Tunisia, Algeria, Sahara"],["Most integrated territory","Coastal Libya"],["Principal inherited administration","French institutions in Algeria and Tunisia"],["Strategic geography","Mediterranean ports and Saharan points and lines"],["Collective title and common legislature","Open"]]
  }),
  "italian-libya":inaArticle({title:"Italian Libya",eyebrow:"Inner colony · Fourth Shore · Mediterranean bridge",infoboxKicker:"Crown colony",infoboxTitle:"Libia Italiana",flag:inaFlag,
    lead:"Italian Libya is the inner colony and administrative bridge of Italy's African empire. Coastal Tripolitania and Cyrenaica contain the region's densest Italian settlement, longest-established colonial government, broadest lira circulation, and most developed Italian municipal institutions. Southern Libya remains a military and oasis territory.",
    canon:"Continuing Italian rule, Fourth Shore ideology, dense coastal settlement, Tripoli's symbolic role, Benghazi and Cyrenaica's military importance, direct lira circulation, municipal development, and military-oasis rule in the south are established. Provincial borders, settler totals, citizenship, land ownership, oil development, governor list, and 1985 constitution remain open.",
    sections:[
      {id:"conquest",title:"Colonial conquest and coercion",html:"<p>Italy seized the Ottoman provinces beginning in 1911 and spent decades imposing control. Deportation, concentration camps, executions, land confiscation, forced movement, and military campaigns shaped colonial society long before the Axis victory.</p>"},
      {id:"shore",title:"The Fourth Shore",html:"<p>The <a href='fourth-shore.html'>Fourth Shore</a> presents coastal Libya as the southern extension of Italy across the Mediterranean. Settler towns, roads, schools, municipalities, farms, ports, and state companies give the slogan material form.</p>"},
      {id:"cities",title:"Tripoli and Benghazi",html:"<p><a href='tripoli-libya.html'>Tripoli</a> is the symbolic capital of Italian Africa and the principal civil-administrative center. <a href='benghazi.html'>Benghazi</a> anchors Cyrenaica, eastern military planning, and routes toward Egypt.</p>"},
      {id:"south",title:"Oases and southern command",html:"<p>Fezzan and the deep interior are governed through garrisons, airfields, radio, oasis agreements, caravan routes, patrols, and selected roads. Ordinary municipal government does not fill the spaces between them.</p>"},
      {id:"economy",title:"Settlement and lira economy",html:"<p>Direct lira circulation, public companies, agriculture, construction, ports, military spending, and settler demand tie the coast closely to Italy. African land, labor, merchants, pastoral exchange, and local institutions remain essential beneath the Italian urban surface.</p>"},
      {id:"religion",title:"Mixed coast, Muslim interior",html:"<p>Italian settlement and Christian institutions make Tripolitanian and Cyrenaican cities religiously mixed. The interior remains overwhelmingly Muslim. Official language of Islamic protection coexists with material preference for Christian land, schools, capital, and office.</p>"},
      {id:"1985",title:"Libya in 1985",html:"<p>Libya is the most integrated North African possession by 1985 and the training ground for officials sent elsewhere in the empire. Its integration remains colonial, racially unequal, and geographically concentrated.</p>"}
    ],related:[{href:"fourth-shore.html",kicker:"Integration doctrine",label:"Fourth Shore"},{href:"tripoli-libya.html",kicker:"Capital",label:"Tripoli"},{href:"benghazi.html",kicker:"Eastern center",label:"Benghazi"},{href:"italian-sahara.html",kicker:"Southern system",label:"Italian Sahara"}],facts:[["Capital","Tripoli"],["Eastern center","Benghazi"],["Sovereign","Kingdom of Italy"],["Colonial doctrine","Fourth Shore"],["Currency","Extensive lira circulation"],["Southern administration","Military, oasis, and route system"],["Population and constitutional form","Open"]]
  }),
  "fourth-shore":inaArticle({title:"Fourth Shore",eyebrow:"Colonial integration doctrine · coastal Libya",infoboxKicker:"Imperial doctrine",infoboxTitle:"Quarta Sponda",
    lead:"The Fourth Shore is the Italian doctrine that treats the developed coast of Libya as a southern extension of the national Mediterranean space. It combines settlement, municipal administration, roads, ports, schools, agriculture, lira circulation, military presence, and Roman imperial symbolism. The doctrine integrates institutions more deeply than elsewhere in North Africa while preserving racial and colonial inequality.",
    canon:"Fourth Shore status for coastal Libya, dense settlement, Italian municipal structures, lira circulation, development, and use as an imperial administrative model are established. Exact legal incorporation, citizenship categories, parliamentary representation, provincial acts, settler franchise, and later reforms remain open.",
    sections:[
      {id:"idea",title:"A shore across the Mediterranean",html:"<p>Fascist Italy described Libya's coast as the fourth side of a national sea bounded by the peninsula and islands. Geography became a claim that settlement and infrastructure could turn colony into national extension.</p>"},
      {id:"institutions",title:"Municipal integration",html:"<p>Italian courts, schools, municipalities, public companies, police, engineering offices, and corporate bodies operate most densely around Tripoli, Benghazi, and settlement belts. Officials trained there later move into Tunisia, Algeria, Egypt, and Saharan commands.</p>"},
      {id:"settlement",title:"Land and settlement",html:"<p>State-supported migration, agricultural schemes, towns, roads, water, credit, and land transfer enlarge the Italian population. These projects depend upon African displacement, unequal land access, regulated labor, and colonial policing.</p>"},
      {id:"limits",title:"Limits of incorporation",html:"<p>The coast is more integrated than the desert interior, and Italians possess privileges unavailable to most Arab and Berber inhabitants. National language does not remove colonial law or create equal political membership.</p>"},
      {id:"postwar",title:"From propaganda to routine",html:"<p>Victory preserves the settler and municipal system. Postwar Italy uses the Fourth Shore as a practical bridge for shipping, officials, lira finance, military logistics, and migration rather than only a ceremonial slogan.</p>"},
      {id:"legacy",title:"Model and warning",html:"<p>Rome sees the Fourth Shore as proof that empire can be integrated. Tunisia and Algeria show why the model cannot be transferred intact to territories with different inherited institutions and settler societies.</p>"}
    ],related:[{href:"italian-libya.html",kicker:"Territorial setting",label:"Italian Libya"},{href:"tripoli-libya.html",kicker:"Symbolic center",label:"Tripoli"},{href:"italian-north-africa.html",kicker:"Wider comparison",label:"Italian North Africa"},{href:"north-african-religious-policy.html",kicker:"Social policy",label:"North African Religious Policy"}],facts:[["Italian name","Quarta Sponda"],["Territorial focus","Coastal Tripolitania and Cyrenaica"],["Instruments","Settlement, municipalities, infrastructure, lira, schools"],["Political character","Colonial integration under unequal law"],["Exact constitutional incorporation","Open"]]
  }),
  "tripoli-libya":inaArticle({title:"Tripoli",eyebrow:"Capital of Italian Libya · symbolic capital of Italian Africa",infoboxKicker:"Colonial capital",infoboxTitle:"Tripoli",landscape:{src:"assets/italian-north-africa-spheres.svg",alt:"Tripoli in the Italian North African coastal system",caption:"Tripoli is the principal civil and symbolic center of the inner colony"},
    lead:"Tripoli is the capital of Italian Libya and the symbolic capital of Italy's African empire. Its port, governor's offices, municipalities, banks, public companies, settler districts, military installations, schools, and markets connect metropolitan Italy to the Fourth Shore and the routes of the western Libyan interior.",
    canon:"Tripoli's capital and symbolic roles, port, Italian municipal concentration, lira economy, settlement, and administrative-training function are established. Population, street plan, governor's residence, firms, municipal franchise, segregation, universities, and 1985 mayor remain open.",
    sections:[{id:"capital",title:"Capital of the inner colony",html:"<p>Tripoli concentrates the governor, senior departments, courts, police, customs, banks, shipping, public works, and colonial associations. It trains officials whose careers extend across Italy's Mediterranean and African territories.</p>"},{id:"port",title:"Port and metropolitan route",html:"<p>Short routes to Sicily and the Italian peninsula carry settlers, troops, mail, machinery, food, capital, and tourists. Port access makes Tripoli easier to supply and supervise than inland districts.</p>"},{id:"city",title:"Colonial municipality",html:"<p>Italian planning, settler districts, public buildings, roads, utilities, schools, and corporate institutions present the Fourth Shore as urban fact. Arab, Berber, Jewish, Maltese, and other communities sustain trade, labor, craft, religion, and older urban life.</p>"},{id:"economy",title:"Lira and public companies",html:"<p>Lira accounts, public investment, construction, agriculture, port services, administration, and military demand make Tripoli the region's most directly Italian financial center.</p>"},{id:"interior",title:"Gateway to the western interior",html:"<p>Roads, airfields, radio, patrols, oasis agreements, and caravan taxation extend southward. The city's command can reach strategic nodes more readily than it can administer every intervening community.</p>"},{id:"1985",title:"Tripoli in 1985",html:"<p>By 1985 Tripoli is a mature colonial metropolis and a showcase of Italian Mediterranean power. Its African majority and unequal institutions prevent the showcase from becoming proof of shared sovereignty.</p>"}],related:[{href:"italian-libya.html",kicker:"Territory",label:"Italian Libya"},{href:"fourth-shore.html",kicker:"Colonial doctrine",label:"Fourth Shore"},{href:"benghazi.html",kicker:"Eastern counterpart",label:"Benghazi"},{href:"italian-sahara.html",kicker:"Interior route",label:"Italian Sahara"}],facts:[["Status","Capital of Italian Libya"],["Imperial role","Symbolic capital of Italian Africa"],["Sea","Mediterranean"],["Functions","Government, port, finance, settlement, training"],["Currency","Lira-dominant colonial economy"],["Population and municipal law","Open"]]
  }),
  "benghazi":inaArticle({title:"Benghazi",eyebrow:"Cyrenaican center · eastern military hinge",infoboxKicker:"Colonial port city",infoboxTitle:"Benghazi",landscape:{src:"assets/italian-north-africa-spheres.svg",alt:"Benghazi on the eastern Libyan coast",caption:"Benghazi anchors Cyrenaica and the approaches toward Egypt"},
    lead:"Benghazi is the principal city of Cyrenaica and the eastern military hinge of Italian Libya. Its port, airfields, garrisons, depots, roads, administration, and settler institutions face Egypt and the central Mediterranean while supporting control of the Cyrenaican interior.",
    canon:"Benghazi's Cyrenaican center, port, military role, Egypt-facing routes, settlement, and connection to southern garrisons are established. Population, harbor capacity, naval units, provincial title, municipal government, reconstruction, and 1985 commander remain open.",
    sections:[{id:"east",title:"Eastern colonial center",html:"<p>Benghazi coordinates Cyrenaican administration, customs, police, courts, military supply, and local commercial life. Its distance from Tripoli gives eastern institutions a distinct regional importance.</p>"},{id:"war",title:"A city shaped by war",html:"<p>Repeated wartime advances and retreats make the port, airfields, roads, depots, and repair capacity strategically central. Axis victory preserves Benghazi as an operating base rather than transferring it to a postwar Libyan state.</p>"},{id:"egypt",title:"Routes toward Egypt",html:"<p>Coastal and desert routes connect Cyrenaica to Egypt and the Suez system. Patrol, weather, fuel, radio, and air support matter as much as formal boundary posts.</p>"},{id:"society",title:"Settler and local society",html:"<p>Italian military and settler institutions coexist with Arab, Berber, Muslim, Jewish, merchant, pastoral, and labor communities beneath unequal law. The city is more integrated into Italian systems than much of its hinterland.</p>"},{id:"interior",title:"Cyrenaican interior",html:"<p>Beyond coastal routes and towns, authority depends on garrisons, local agreements, religious and tribal intermediaries, wells, markets, and mobile forces.</p>"},{id:"1985",title:"Benghazi in 1985",html:"<p>By 1985 Benghazi remains more military than Tripoli and more closely tied to the Egyptian frontier. Its exact civil-military balance remains open.</p>"}],related:[{href:"italian-libya.html",kicker:"Territory",label:"Italian Libya"},{href:"tripoli-libya.html",kicker:"Western capital",label:"Tripoli"},{href:"north-african-colonial-security.html",kicker:"Security system",label:"North African Colonial Security"},{href:"egypt.html",kicker:"Eastern neighbor",label:"Egypt"}],facts:[["Territory","Cyrenaica, Italian Libya"],["Sea","Mediterranean"],["Principal role","Eastern military and administrative center"],["Strategic direction","Egypt and the Suez approaches"],["Interior system","Garrisons, routes, airfields, local agreements"],["Population and command","Open"]]
  }),
  "italian-tunisia":inaArticle({title:"Italian Tunisia",eyebrow:"Compact supervised territory · Sicily approaches",infoboxKicker:"Crown colony or supervised territory",infoboxTitle:"Tunisia under Italian rule",flag:inaFlag,
    lead:"Italian Tunisia is the compact North African territory governed through preserved Tunisian and French machinery beneath Italian control of customs, ports, foreign affairs, security, and strategic investment. Proximity to Sicily, commercial development, established Italian and Maltese communities, and the Tunis–Bizerte axis make it easier to integrate than Algeria.",
    canon:"Italian sovereignty or equivalent direct imperial control, retained Tunisian and French administration, strategic Italian reserve, Tunis and Bizerte's roles, mixed communities, rapid lira integration, and coastal Christian growth are established. Formal protectorate or colony title, beylical status, borders, governor list, legislature, population, currency transition, and 1985 constitution remain open.",
    sections:[{id:"transfer",title:"Transfer into the Italian system",html:"<p>Axis victory removes French strategic sovereignty while leaving local offices, commercial practices, municipalities, courts, and personnel in place. Rome takes the functions that control external alignment and the economic route.</p>"},{id:"compact",title:"A compact Mediterranean territory",html:"<p>Short distances, developed towns, rail and road links, agriculture, ports, and proximity to Sicily allow more regular supervision than in Algeria or the Sahara.</p>"},{id:"cities",title:"Tunis and Bizerte",html:"<p><a href='tunis.html'>Tunis</a> becomes a principal administrative and commercial center. <a href='bizerte.html'>Bizerte</a> becomes a major naval position controlling the approaches between Sicily, Sardinia, and the western Mediterranean.</p>"},{id:"machinery",title:"Preserved administration",html:"<p>Tunisian and French officials continue useful taxation, courts, municipal work, records, and commerce. Italian authorities supervise customs, ports, security, foreign relations, senior appointments, and strategic projects.</p>"},{id:"society",title:"A mixed coastal society",html:"<p>Italian, French, Maltese, Jewish, Arab, and other communities remain economically important. Christian settlement and institutions grow in Tunis, Bizerte, Sfax, and selected agricultural districts while most of the countryside remains Muslim.</p>"},{id:"economy",title:"Customs and lira integration",html:"<p>Rome redirects shipping, credit, imports, investment, and concessions toward Italy. Lira circulation grows quickly, though inherited accounts and commercial practices do not disappear immediately.</p>"},{id:"1985",title:"Tunisia in 1985",html:"<p>By 1985 Tunisia is closely connected to the Italian Mediterranean economy while retaining a visible local institutional identity. Its exact legal dignity remains open.</p>"}],related:[{href:"tunis.html",kicker:"Capital center",label:"Tunis"},{href:"bizerte.html",kicker:"Naval base",label:"Bizerte"},{href:"italian-north-africa.html",kicker:"Regional system",label:"Italian North Africa"},{href:"north-african-religious-policy.html",kicker:"Social policy",label:"North African Religious Policy"}],facts:[["Administrative center","Tunis"],["Principal naval base","Bizerte"],["Sovereign power","Kingdom of Italy"],["Inherited machinery","Tunisian and French offices"],["Italian reserve","Customs, ports, security, foreign affairs"],["Formal title and constitution","Open"]]
  }),
  "tunis":inaArticle({title:"Tunis",eyebrow:"Administrative and commercial capital · Italian Tunisia",infoboxKicker:"Colonial capital",infoboxTitle:"Tunis",landscape:{src:"assets/italian-north-africa-spheres.svg",alt:"Tunis in the Italian North African coastal system",caption:"Tunis joins compact territorial administration to Mediterranean commerce"},
    lead:"Tunis is the administrative and commercial capital of Italian Tunisia and one of the principal cities of the Italian Mediterranean empire. Its port connections, government offices, banks, markets, railways, mixed communities, schools, and religious institutions make it the civil counterpart to Bizerte's naval role.",canon:"Tunis's administrative and commercial primacy, mixed communities, inherited offices, Italian strategic supervision, lira integration, and Christian institutional growth are established. Population, municipal law, beylical court, port organization, banks, neighborhoods, and 1985 leadership remain open.",
    sections:[{id:"capital",title:"Capital under layered government",html:"<p>Tunisian and French offices conduct much ordinary administration while Italian authorities supervise strategic appointments, customs, security, ports, investment, and external relations.</p>"},{id:"commerce",title:"Mediterranean commercial center",html:"<p>Shipping, rail, wholesale trade, banking, agriculture, processing, markets, and services connect the Tunisian interior to Sicily, Italy, and the western Mediterranean.</p>"},{id:"communities",title:"A city of several communities",html:"<p>Arab, Jewish, Italian, French, Maltese, and other communities sustain distinct schools, worship, neighborhoods, businesses, associations, and political loyalties.</p>"},{id:"institutions",title:"Inherited and imperial institutions",html:"<p>Rome retains offices and professionals capable of keeping accounts, courts, tax rolls, utilities, and commerce running. Italian ministries and firms redirect the most strategic flows.</p>"},{id:"religion",title:"Religious and educational competition",html:"<p>Christian schools, hospitals, parishes, and missions gain resources. Muslim institutions remain central to the larger population, while Jewish institutions preserve a major urban presence under a settlement whose exact law remains open.</p>"},{id:"1985",title:"Tunis in 1985",html:"<p>By 1985 Tunis is an established imperial commercial capital whose local administration is more continuous than its sovereign history. Italian power is clearest at the points controlling money, security, and movement.</p>"}],related:[{href:"italian-tunisia.html",kicker:"Territory",label:"Italian Tunisia"},{href:"bizerte.html",kicker:"Naval counterpart",label:"Bizerte"},{href:"italian-north-africa.html",kicker:"Regional system",label:"Italian North Africa"},{href:"latin-civil-aviation-tourism.html",kicker:"Mobility and visitors",label:"Latin Civil Aviation and Tourism"}],facts:[["Status","Administrative and commercial capital of Tunisia"],["Strategic supervisor","Kingdom of Italy"],["Functions","Government, trade, finance, rail, education"],["Communities","Arab, Jewish, Italian, French, Maltese, and others"],["Population and municipal constitution","Open"]]
  }),
  "bizerte":inaArticle({title:"Bizerte",eyebrow:"Naval base · Sicily–western Mediterranean hinge",infoboxKicker:"Strategic port",infoboxTitle:"Bizerte",landscape:{src:"assets/italian-north-africa-spheres.svg",alt:"Bizerte in the North African coastal system",caption:"Bizerte is the principal Tunisian naval node inside Italy's Mediterranean chain"},
    lead:"Bizerte is the principal naval position of Italian Tunisia and a major base in Rome's western Mediterranean system. Its harbor, dockyards, fuel, air support, coastal defenses, repair capacity, and proximity to Sicily give Italy control over a route that joins North Africa to the central sea.",canon:"Bizerte's major naval role, Italian strategic control, port and repair functions, proximity to Sicily, and connection to Tunis are established. Base perimeter, fleet units, dockyard capacity, municipal authority, civilian population, and 1985 commander remain open.",
    sections:[{id:"harbor",title:"Strategic harbor",html:"<p>Bizerte's protected water and existing naval infrastructure make it too valuable to leave under purely local administration. Italy takes direct control of the base and its approaches.</p>"},{id:"chain",title:"Mediterranean base chain",html:"<p>The port works with Sicily, Sardinia, Malta, Tripoli, Algiers, and other naval stations. Fuel, repair, patrol, aviation, communications, weather, and convoy services make the chain operational.</p>"},{id:"tunis",title:"Tunis–Bizerte axis",html:"<p>Road and rail connect the naval base to <a href='tunis.html'>Tunis</a>, supplies, labor, administration, and the commercial interior. The two cities divide military and civil functions.</p>"},{id:"society",title:"Base city and local society",html:"<p>Italian naval personnel and contractors coexist with Tunisian, French, Maltese, and other workers, merchants, fishermen, families, and religious institutions under heightened surveillance.</p>"},{id:"security",title:"Direct strategic supervision",html:"<p>Customs, restricted zones, fuel storage, dock access, radio, airfields, and coastal defenses remain under Italian command even where municipal services are locally staffed.</p>"},{id:"1985",title:"Bizerte in 1985",html:"<p>By 1985 Bizerte is a permanent imperial naval city rather than an occupied French base. Its exact relationship to Tunisian civil law remains open.</p>"}],related:[{href:"italian-tunisia.html",kicker:"Territory",label:"Italian Tunisia"},{href:"tunis.html",kicker:"Civil capital",label:"Tunis"},{href:"regia-marina-postwar.html",kicker:"Naval system",label:"Regia Marina after the War"},{href:"latin-naval-system.html",kicker:"Bloc fleet",label:"Latin Naval System"}],facts:[["Territory","Italian Tunisia"],["Sea","Mediterranean"],["Principal role","Naval base and repair node"],["Nearest civil center","Tunis"],["Strategic authority","Italian naval command"],["Base limits and fleet units","Open"]]
  }),
  "italian-algeria":inaArticle({title:"Italian Algeria",eyebrow:"French colonial society under an Italian roof",infoboxKicker:"Crown colony or occupied colonial system",infoboxTitle:"Algeria under Italian sovereignty",flag:inaFlag,
    lead:"Italian Algeria is the largest and least settled of Italy's North African coastal possessions. Rome inherits a French-speaking bureaucracy, municipalities, banks, commercial law, and a large European settler population alongside Arab and Berber societies and nationalist movements. Italy controls ports, customs, airfields, trunk routes, police strategy, and concessions while much ordinary life continues through inherited institutions.",
    canon:"Italian sovereignty, retained French institutions, settler continuity under loyalty oaths, French administrative importance, lira-franc coexistence, Italian concessions, cultivation of Arab and Berber notables, Italian strategic control, and simultaneous French, Arab, and Berber opposition are established. Exact borders, constitutional title, settler numbers, nationality law, insurgency chronology, governor list, currencies, and 1985 institutions remain open.",
    sections:[{id:"inheritance",title:"A French colony inherited by Italy",html:"<p>Italy acquires Algeria after the defeat of Britain's Torch expedition and the wider Axis settlement. Rome lacks the officials and legitimacy to discard the French colonial state and rebuild it at once.</p>"},{id:"bargain",title:"The loyalty bargain",html:"<p>French officials and settlers may remain when they swear loyalty and accept Italian sovereignty. French law, municipal practice, language, banks, and commercial records continue provisionally while Italy takes the strategic summit.</p>"},{id:"strategic",title:"Italian points of control",html:"<p>Ports, customs, principal roads, airfields, police headquarters, foreign access, military communications, and major concessions receive Italian command. <a href='algiers.html'>Algiers</a> is the administrative and political center of the system.</p>"},{id:"communities",title:"Settler, Arab, and Berber politics",html:"<p>The <a href='french-settler-society-algeria.html'>French settler society</a> seeks security and retained privilege while containing restorationist currents. Arab and Berber notables receive office, credit, land protection, or representation as counterweights. Nationalists reject both French and Italian sovereignty.</p>"},{id:"currency",title:"Franc, lira, and concessions",html:"<p>French accounts and the franc coexist with the lira during a long transition. Italian firms gain preferred credit, infrastructure, mining, agriculture, and service concessions. Economic integration is negotiated through institutions Rome does not fully own.</p>"},{id:"security",title:"An uneasy security order",html:"<p>French underground nationalism, indigenous resistance, communal violence, smuggling, and Italian frustration persist. Rome's central policy is to prevent two hostile constituencies from forming a durable common front.</p>"},{id:"religion",title:"Christian continuity and selective expansion",html:"<p>European settlers preserve a large Christian population. Italian, Spanish, Maltese, Occitan, and Levantine migration adds to it. Some Kabyle and other Berber districts develop Christian institutions through schools and protected conversion, while most of the population remains Muslim.</p>"},{id:"1985",title:"Algeria in 1985",html:"<p>By 1985 Italy can hold the coast and principal corridors. It cannot claim that Algeria has become an Italian national extension or that its competing peoples accept the imperial settlement.</p>"}],related:[{href:"algiers.html",kicker:"Administrative center",label:"Algiers"},{href:"french-settler-society-algeria.html",kicker:"Inherited society",label:"French Settlers under Italian Rule"},{href:"north-african-colonial-security.html",kicker:"Coercive system",label:"North African Colonial Security"},{href:"axis-counteroffensive-algeria.html",kicker:"Wartime origin",label:"Axis Counteroffensive in Algeria"}],facts:[["Administrative center","Algiers"],["Sovereign power","Kingdom of Italy"],["Inherited system","French bureaucracy, law, municipalities, banks"],["Principal populations","European settlers, Arab and Berber societies"],["Currencies","Lira and inherited franc system during transition"],["Administrative result","Governable, not integrated"],["Formal title, borders, and 1985 constitution","Open"]]
  }),
  "algiers":inaArticle({title:"Algiers",eyebrow:"Administrative capital · inherited French metropolis",infoboxKicker:"Colonial capital",infoboxTitle:"Algiers",landscape:{src:"assets/italian-north-africa-spheres.svg",alt:"Algiers in the Italian North African coastal system",caption:"Algiers is the political center of a French institutional society under Italian sovereignty"},
    lead:"Algiers is the administrative capital of Italian Algeria and the city in which inherited French institutions meet Italian imperial command most directly. Its port, municipalities, courts, police, banks, settler associations, Arab and Berber communities, military headquarters, and memory of the failed British bridgehead make it the political center of the most difficult North African possession.",canon:"Algiers's capital, port, inherited French institutional density, Italian strategic command, settler politics, indigenous communities, and wartime significance are established. Population, municipal government, renamed institutions, legal language, base perimeter, universities, and 1985 leadership remain open.",
    sections:[{id:"war",title:"From Torch bridgehead to Italian capital",html:"<p>British forces establish a bridgehead during Operation Torch, then capitulate after the Axis counteroffensive makes evacuation impossible. The postwar settlement places the city's strategic institutions beneath Italy.</p>"},{id:"administration",title:"Inherited French metropolis",html:"<p>French-speaking courts, municipal offices, banks, firms, schools, records, and professionals cannot be replaced quickly. Italian officials occupy the strategic summit and supervise loyalty, security, customs, and concessions.</p>"},{id:"port",title:"Port and military headquarters",html:"<p>The harbor connects Algeria to Italy, Spain, Occitania, Tunisia, and Atlantic approaches. Naval access, airfields, radio, depots, customs, and headquarters receive direct imperial protection.</p>"},{id:"politics",title:"Three oppositions in one city",html:"<p>French restorationists, Arab and Berber nationalists, and Italian colonial officials pursue incompatible futures. Settler associations, mosques, schools, universities, labor, newspapers, and professional networks turn urban politics into a permanent security concern.</p>"},{id:"economy",title:"Banks, francs, and lira",html:"<p>Inherited French finance and commercial law continue while Italian credit and firms enter strategic sectors. The city manages a monetary transition that is slower and more contested than in Tripoli or Tunis.</p>"},{id:"1985",title:"Algiers in 1985",html:"<p>By 1985 Algiers is a mature imperial capital whose institutions remain visibly French in language and practice. Italian sovereignty controls the route while never fully absorbing the city.</p>"}],related:[{href:"italian-algeria.html",kicker:"Territory",label:"Italian Algeria"},{href:"french-settler-society-algeria.html",kicker:"Settler politics",label:"French Settlers under Italian Rule"},{href:"axis-counteroffensive-algeria.html",kicker:"Wartime turning point",label:"Axis Counteroffensive in Algeria"},{href:"algiers-capitulation.html",kicker:"End of the bridgehead",label:"Algiers Capitulation"}],facts:[["Status","Administrative capital of Italian Algeria"],["Sea","Mediterranean"],["Inherited language","French remains indispensable"],["Strategic authority","Kingdom of Italy"],["Functions","Port, courts, finance, police, military headquarters"],["Population and municipal law","Open"]]
  }),
  "french-settler-society-algeria":inaArticle({title:"French Settler Society under Italian Rule",eyebrow:"Algeria · loyalty oaths · inherited privilege · restoration politics",infoboxKicker:"Colonial social system",infoboxTitle:"European settlers in Italian Algeria",
    lead:"French settler society under Italian rule is the inherited European municipal, commercial, landed, professional, and political order that Rome preserves in Algeria after 1947. Settlers may retain property, offices, firms, schools, associations, and much French law when they swear loyalty and accept Italian sovereignty. Their usefulness and potential restorationism make them both partners and security subjects.",canon:"A large inherited French settler population, loyalty bargain, retained municipal and commercial institutions, French administrative language, continuing privileges, restorationist opposition, Italian concessions, and use of Arab and Berber notables as counterweights are established. Population, citizenship categories, voting rights, land distribution, parties, expulsions, arrests, migration, and 1985 identity remain open.",
    sections:[{id:"inheritance",title:"An established colonial society",html:"<p>Italy does not inherit empty land. It inherits municipalities, farms, firms, professions, banks, schools, churches, clubs, newspapers, families, and property relations built through French conquest and settlement.</p>"},{id:"oath",title:"Property in exchange for loyalty",html:"<p>Rome's practical bargain preserves useful institutions and avoids mass flight or administrative collapse. Loyalty oaths and acceptance of Italian strategic supremacy become conditions for continued office and protection.</p>"},{id:"language",title:"French remains indispensable",html:"<p>Italian becomes the imperial language, yet French remains necessary in courts, municipal records, banking, education, commerce, and professional life. Bilingual administration records Italy's limited capacity to absorb Algeria.</p>"},{id:"restoration",title:"French restorationism",html:"<p>Some settlers accommodate the new state to protect family and property. Others sustain underground loyalty to France, commemorate the lost order, move money and information, or resist Italianization.</p>"},{id:"privilege",title:"Privilege and indigenous exclusion",html:"<p>Conflict with Italy does not make the settler order anti-colonial. Settlers defend land, municipal power, schools, employment, policing, and legal privileges constructed over Arab and Berber exclusion.</p>"},{id:"counterweights",title:"Rome's counterweights",html:"<p>Italian officials cultivate Arab and Berber notables, extend selected local offices, protect some land claims, and offer credit or representation. These measures divide opposition and pressure French institutions rather than create equality.</p>"},{id:"1985",title:"A second-generation imperial identity",html:"<p>By 1985 many families have spent decades under Italian sovereignty while retaining French language and social memory. Whether they become a distinct Algerian-European community or remain politically French is open.</p>"}],related:[{href:"italian-algeria.html",kicker:"Territorial setting",label:"Italian Algeria"},{href:"algiers.html",kicker:"Urban center",label:"Algiers"},{href:"north-african-colonial-security.html",kicker:"State supervision",label:"North African Colonial Security"},{href:"northern-france.html",kicker:"Lost metropolitan reference",label:"Northern France"}],facts:[["Principal territory","Italian Algeria"],["Institutional language","French"],["Condition of retention","Loyalty to Italian sovereignty"],["Preserved fields","Municipalities, commerce, property, schools, professions"],["Principal political tension","Accommodation versus French restoration"],["Population and citizenship law","Open"]]
  }),
  "italian-sahara":inaArticle({title:"Italian Sahara",eyebrow:"Oases · airfields · radio posts · survey maps",infoboxKicker:"Military and concession territory",infoboxTitle:"Saharan acquisitions under Italian rule",flag:inaFlag,
    lead:"The Italian Sahara is the collective military, transport, survey, and concession geography of Rome's desert acquisitions. Italy controls selected oasis routes, airfields, radio and weather posts, caravan taxes, mines, border stations, and roads. It does not establish ordinary government across every interval shown in imperial colors on the map.",canon:"Saharan points-and-lines rule, oasis agreements, airfields, radio and weather, caravan taxation, mineral surveys, roads, border posts, strategic depth, map prestige, and exclusion of rivals are established. Exact frontiers, territorial names, colonial transfers, population, mines, commands, municipal jurisdictions, and 1985 administrative map remain open.",
    sections:[{id:"map",title:"A political map and military geography",html:"<p>The Sahara appears as territorial continuity in atlases while functioning through sparse nodes. A colored frontier may indicate strategic exclusion more reliably than daily administration.</p>"},{id:"routes",title:"The route system",html:"<p>The <a href='saharan-route-system.html'>Saharan Route System</a> joins oases, wells, roads, tracks, airfields, radio, weather, patrol posts, and caravan markets. Loss of one node can matter more than nominal control of a vast surrounding district.</p>"},{id:"government",title:"Agreements and garrisons",html:"<p>Military officers bargain with oasis authorities, merchants, pastoral leaders, guides, and local police. Patrol, subsidy, tax, access, water, and intelligence agreements give the state reach at low administrative density.</p>"},{id:"air",title:"Air routes and weather",html:"<p>Aircraft carry officials, mail, reconnaissance, medicine, survey teams, communications equipment, and rapid force. Weather and radio stations make desert routes usable across the Mediterranean, Africa, and the Red Sea.</p>"},{id:"minerals",title:"Survey and concessions",html:"<p>Geological surveys and concessions search for fuels, metals, salts, and other minerals. Exploration is established as a function; specific discoveries, fields, firms, and output remain open.</p>"},{id:"strategy",title:"Depth and exclusion",html:"<p>The Sahara gives prestige, buffer space, overflight routes, border leverage, and a barrier against British or German return. These values can justify posts whose local revenue is negligible.</p>"},{id:"1985",title:"The Sahara in 1985",html:"<p>By 1985 technology has improved navigation, radio, aviation, weather, survey, and patrol. The governing principle remains selective control of movement rather than dense occupation.</p>"}],related:[{href:"saharan-route-system.html",kicker:"Practical geography",label:"Saharan Route System"},{href:"north-african-colonial-security.html",kicker:"Military authority",label:"North African Colonial Security"},{href:"italian-libya.html",kicker:"Northern base",label:"Italian Libya"},{href:"italian-algeria.html",kicker:"Western base",label:"Italian Algeria"}],facts:[["Political status","Italian military and concession territories"],["Government form","Points and lines"],["Controlled nodes","Oases, airfields, radio, roads, border posts"],["Economic functions","Caravan tax, surveys, concessions, transit"],["Strategic functions","Depth, air routes, exclusion of rivals"],["Exact frontiers and discoveries","Open"]]
  }),
  "saharan-route-system":inaArticle({title:"Saharan Route System",eyebrow:"Air routes · oases · radio · roads · caravan taxation",infoboxKicker:"Desert infrastructure system",infoboxTitle:"Italian Saharan points and lines",landscape:{src:"assets/italian-north-africa-spheres.svg",alt:"Saharan routes extending south from the North African coast",caption:"The schematic shows the governing principle and leaves exact roads and frontiers open"},
    lead:"The Saharan Route System is the network of oases, wells, caravan markets, roads, tracks, airfields, radio and weather stations, patrol posts, depots, survey camps, and border stations that gives Italian desert claims practical content. It links the North African coast to inland strategic depth while leaving most land outside continuous ordinary administration.",canon:"The listed infrastructure, caravan taxation, military patrol, mineral survey, air routes, border stations, and selective-control principle are established. Exact routes, names, distances, airfields, stations, road standards, operators, traffic, budgets, and cross-border treaties remain open.",
    sections:[{id:"logic",title:"Movement is the governable object",html:"<p>The desert state cannot supervise every square mile. It governs access to water, fuel, markets, radio, landing grounds, customs points, and the safest routes between them.</p>"},{id:"oases",title:"Oases and local agreements",html:"<p>Oasis authorities, merchants, cultivators, pastoral communities, guides, and police provide knowledge and services. Tax, subsidy, water, market, and security agreements connect them to garrisons.</p>"},{id:"air",title:"Airfields, radio, and weather",html:"<p>Air routes compress distances while increasing dependence on fuel, maintenance, navigation, weather, rescue, and communications. A radio or weather post can be a strategic asset far beyond its population.</p>"},{id:"roads",title:"Roads, tracks, and patrol",html:"<p>Selected roads support trucks and military columns. Older tracks and caravan routes remain important where motor transport is expensive or unreliable.</p>"},{id:"tax",title:"Caravan and concession revenue",html:"<p>Markets, permits, customs, caravan taxes, transport fees, and mineral concessions convert movement into revenue. Fiscal value remains secondary to strategy across much of the system.</p>"},{id:"limits",title:"Intervals beyond routine control",html:"<p>Between nodes, authority may mean occasional reconnaissance, a treaty claim, or denial of rival access. Maps therefore overstate the density of Italian government.</p>"}],related:[{href:"italian-sahara.html",kicker:"Territorial system",label:"Italian Sahara"},{href:"italian-north-africa.html",kicker:"Coastal bases",label:"Italian North Africa"},{href:"north-african-colonial-security.html",kicker:"Patrol and garrison",label:"North African Colonial Security"},{href:"benghazi.html",kicker:"Eastern gateway",label:"Benghazi"}],facts:[["Network nodes","Oases, wells, airfields, radio, weather, posts"],["Surface movement","Roads, tracks, caravans, patrols"],["Revenue","Taxes, permits, markets, concessions"],["Primary purpose","Strategic access and exclusion"],["Exact route registry","Open"]]
  }),
  "north-african-religious-policy":inaArticle({title:"North African Religious Policy",eyebrow:"Christian preference · Muslim continuity · settler institutions",infoboxKicker:"Imperial religious settlement",infoboxTitle:"Religion in Italian North Africa",
    lead:"North African Religious Policy is Italy's attempt to enlarge durable Christian institutions across Libya, Tunisia, and Algeria while governing overwhelmingly Muslim interiors. The state preserves European settlers, encourages additional Christian migration, funds schools and missions, protects conversion, and favors Christian access to land, education, office, and capital. It also maintains legal Islam because the empire cannot function through permanent religious war.",canon:"Christian settler retention, wider Christian migration, schools, protected conversion, institutional preference, supervised Muslim public life, mixed urban families, refugee resettlement, coastal concentration, regional Berber missions, and continued Muslim majorities inland are established. Census shares, dioceses, Islamic councils, Jewish status, marriage law, conversion totals, named missions, and 1985 religious leadership remain open.",
    sections:[{id:"limits",title:"Institutions before mass conversion",html:"<p>Mission budgets cannot transform an overwhelmingly Muslim countryside quickly. Italy therefore builds demographic and institutional weight through settlement, migration, schools, hospitals, careers, family policy, and protected conversion.</p>"},{id:"migration",title:"Christian settlement and refugees",html:"<p>Italian, French, Spanish, Occitan, Maltese, Greek, and Levantine Christians remain or migrate into coastal cities and agricultural districts. Christian refugees can be placed where settlement and labor policy overlap.</p>"},{id:"schools",title:"Schools, hospitals, and advancement",html:"<p>Christian institutions receive permissions, money, property, and links to urban employment. Education and medicine make conversion or Christian affiliation materially significant even where coercion is indirect.</p>"},{id:"islam",title:"Islam under supervision",html:"<p>Mosques, scholars, courts, charities, festivals, and local authorities remain necessary. The state supervises political organization and reduces some institutional independence while publicly claiming protection and tolerance.</p>"},{id:"territories",title:"Different territorial outcomes",html:"<p>Algeria retains the largest Christian component through French settlers and later migration. Tunisia develops substantial Christian coastal cities. Libya's Christian population concentrates in Tripolitanian and Cyrenaican settlement belts while the interior remains overwhelmingly Muslim.</p>"},{id:"berber",title:"Regional Berber missions",html:"<p>Some Kabyle and other Berber districts may develop visible Catholic or Orthodox institutions through schools, protection, and distance from Arab central authority. This is a regional direction rather than a registered mass conversion.</p>"},{id:"jewish",title:"Jewish communities",html:"<p>Jewish institutions and commerce remain important in several cities. Their exact treatment under the victorious Italian racial and imperial order requires explicit canon and cannot be inferred from Christian–Muslim policy alone.</p>"}],related:[{href:"italian-north-africa.html",kicker:"Regional setting",label:"Italian North Africa"},{href:"italian-algeria.html",kicker:"Largest Christian component",label:"Italian Algeria"},{href:"italian-tunisia.html",kicker:"Mixed coast",label:"Italian Tunisia"},{href:"italian-libya.html",kicker:"Settlement belts",label:"Italian Libya"}],facts:[["State preference","Christian institutions and settlement"],["Muslim status","Legal, supervised, and locally indispensable"],["Principal instruments","Migration, schools, hospitals, office, land, capital"],["Strongest Christian component","Algeria"],["Most Muslim areas","Rural and desert interiors"],["Censuses and detailed religious law","Open"]]
  }),
  "north-african-colonial-security":inaArticle({title:"North African Colonial Security",eyebrow:"Ports · corridors · police · airfields · divided opposition",infoboxKicker:"Imperial security system",infoboxTitle:"Security in Italian North Africa",landscape:{src:"assets/italian-north-africa-authority.svg",alt:"Differentiated authority beneath Italian strategic control",caption:"Security priorities vary with each territory's inherited institutions and administrative depth"},
    lead:"North African Colonial Security is the Italian-led system protecting ports, customs, trunk roads, railways, airfields, radio, garrisons, settler districts, concessions, and political authority across four very different territories. Direct municipal policing is most developed in Libya, inherited offices remain important in Tunisia and Algeria, and mobile military rule dominates the Sahara.",canon:"Italian control of strategic security, retained local and French personnel, coastal garrisons, police, mobile and air response, route protection, surveillance, divided-opposition strategy, and thinner Saharan authority are established. Service names, commands, unit lists, intelligence agencies, commanders, strengths, equipment, emergencies, casualties, and 1985 order of battle remain open.",
    sections:[{id:"reserve",title:"Italian strategic reserve",html:"<p>Rome retains external defense, naval bases, aviation, military communications, senior police strategy, customs security, mobile reserves, and access to strategic installations.</p>"},{id:"libya",title:"Municipal and colonial policing in Libya",html:"<p>Long colonial rule supplies Italian municipalities, police, garrisons, settler institutions, roads, and administrative personnel. Southern command relies more heavily on oases, patrols, aircraft, and agreements.</p>"},{id:"tunisia",title:"Supervised inherited machinery in Tunisia",html:"<p>Tunisian and French police and civil officials continue much routine work beneath Italian command of ports, customs, intelligence, and high-level security. Compact geography allows rapid reinforcement.</p>"},{id:"algeria",title:"Preventing a common Algerian front",html:"<p>Italy monitors French restorationists, Arab and Berber nationalists, settler associations, labor, universities, religious institutions, smuggling, and local violence. Patronage and limited offices divide constituencies that might otherwise unite.</p>"},{id:"sahara",title:"Garrisons and air mobility in the Sahara",html:"<p>Posts, patrols, airfields, radio, weather, guides, wells, and oasis agreements secure routes. Control of movement matters more than permanent occupation of territory between nodes.</p>"},{id:"personnel",title:"Italian command and local personnel",html:"<p>Italian officers and specialists retain the strategic ceiling. Local police, soldiers, interpreters, officials, settlers, merchants, and notables provide language, presence, records, and intelligence.</p>"},{id:"1985",title:"A durable coercive geography",html:"<p>By 1985 the system is technically stronger and more locally staffed than in 1947. Its purpose remains the preservation of foreign sovereignty against several incompatible forms of opposition.</p>"}],related:[{href:"italian-north-africa.html",kicker:"Regional system",label:"Italian North Africa"},{href:"italian-algeria.html",kicker:"Hardest possession",label:"Italian Algeria"},{href:"saharan-route-system.html",kicker:"Desert network",label:"Saharan Route System"},{href:"regia-marina-postwar.html",kicker:"Maritime reserve",label:"Regia Marina after the War"}],facts:[["Supreme authority","Kingdom of Italy"],["Protected systems","Ports, customs, roads, rail, airfields, radio, concessions"],["Routine personnel","Italian, inherited French and Tunisian, and local forces"],["Algerian doctrine","Divide restorationist, nationalist, and communal opposition"],["Saharan doctrine","Mobile control of points and lines"],["1985 command and force totals","Open"]]
  })
});
